from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_32 = Integer(32); _sage_const_3 = Integer(3); _sage_const_129 = Integer(129); _sage_const_1en10 = RealNumber('1e-10')
def choose(n, k):
    if k < _sage_const_0  or k > n: return _sage_const_0 
    return binomial(n, k)

def a(n):
    if n == _sage_const_0 : return _sage_const_1 
    r = n - _sage_const_1 
    s = _sage_const_0 
    for k in range(n + _sage_const_1 ):
        s += choose(n, k) * choose(_sage_const_2 *n + k - _sage_const_1 , r)
    return s

m = _sage_const_32 
print("Precomputing b(n)...")
b = [QQ(a(m*i)) for i in range(_sage_const_3 *m + _sage_const_3 )]
print("b(n) precomputed.")

# We set up the linear system for P and Q
# P has degree 2m (64). Coeffs c0..c64
# Q has degree 2m (64). Coeffs d0..d64. But Q is evaluated at n^2, so Q(n^2) = sum d_i n^(2i).
# We set d64 = 1.
# Total variables: c0..c64, d0..d63 (129 variables)

# We use 3m+1 (97) recurrence equations (n = 1..97) and m (32) symmetry equations
# This gives exactly 129 equations.
# Symmetry equations: P(k) = P(1-k) for k = 1..32

# Let's define the variables in Sage
ring = QQ['c0', 'c1', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8', 'c9', 'c10', 'c11', 'c12', 'c13', 'c14', 'c15', 'c16', 'c17', 'c18', 'c19', 'c20', 'c21', 'c22', 'c23', 'c24', 'c25', 'c26', 'c27', 'c28', 'c29', 'c30', 'c31', 'c32', 'c33', 'c34', 'c35', 'c36', 'c37', 'c38', 'c39', 'c40', 'c41', 'c42', 'c43', 'c44', 'c45', 'c46', 'c47', 'c48', 'c49', 'c50', 'c51', 'c52', 'c53', 'c54', 'c55', 'c56', 'c57', 'c58', 'c59', 'c60', 'c61', 'c62', 'c63', 'c64', 'd0', 'd1', 'd2', 'd3', 'd4', 'd5', 'd6', 'd7', 'd8', 'd9', 'd10', 'd11', 'd12', 'd13', 'd14', 'd15', 'd16', 'd17', 'd18', 'd19', 'd20', 'd21', 'd22', 'd23', 'd24', 'd25', 'd26', 'd27', 'd28', 'd29', 'd30', 'd31', 'd32', 'd33', 'd34', 'd35', 'd36', 'd37', 'd38', 'd39', 'd40', 'd41', 'd42', 'd43', 'd44', 'd45', 'd46', 'd47', 'd48', 'd49', 'd50', 'd51', 'd52', 'd53', 'd54', 'd55', 'd56', 'd57', 'd58', 'd59', 'd60', 'd61', 'd62', 'd63']
vars = list(ring.gens())

eqs = []
# Recurrence equations
for n in range(_sage_const_1 , _sage_const_3 *m + _sage_const_2 ):
    plus = prod(_sage_const_2 *m*n + k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
    minus = prod(_sage_const_2 *m*n - k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
    
    P_pos = sum(vars[i] * n**i for i in range(_sage_const_2 *m + _sage_const_1 ))
    P_neg = sum(vars[i] * (-n)**i for i in range(_sage_const_2 *m + _sage_const_1 ))
    
    # (-1)^32 = 1
    Q_val = sum(vars[_sage_const_2 *m + _sage_const_1  + i] * (n**_sage_const_2 )**i for i in range(_sage_const_2 *m)) + (n**_sage_const_2 )**(_sage_const_2 *m) # d64 = 1
    
    eq = plus * P_pos * b[n+_sage_const_1 ] + minus * P_neg * b[n-_sage_const_1 ] - Q_val * b[n]
    eqs.append(eq)

# Symmetry equations
for k in range(_sage_const_1 , m + _sage_const_1 ):
    eq = sum(vars[i] * k**i for i in range(_sage_const_2 *m + _sage_const_1 )) - sum(vars[i] * (_sage_const_1  - k)**i for i in range(_sage_const_2 *m + _sage_const_1 ))
    eqs.append(eq)

print("Solving the linear system...")
# We solve the system of 129 equations in 129 variables
# Let's convert to a matrix form over QQ
A = matrix(QQ, _sage_const_129 , _sage_const_129 )
B = vector(QQ, _sage_const_129 )

for r_idx, eq in enumerate(eqs):
    # We want to extract coefficients of vars
    # eq is of the form LHS - Q_val_d64 * b[n]
    # Q_val_d64 has the term (n^2)^64 * b[n]
    # So the constant term of eq with respect to vars is the term from d64 = 1, which is - (n^2)^64 * b[n]
    # Wait, let's just extract the constant term and coefficients of vars directly in Sage
    for c_idx, v in enumerate(vars):
        A[r_idx, c_idx] = eq.coefficient(v)
    # The constant term is eq evaluated with all vars = 0
    B[r_idx] = -eq.subs({v: _sage_const_0  for v in vars})

print("Solving matrix equation...")
sol = A.solve_right(B)
print("System solved!")

d_sol = [sol[_sage_const_2 *m + _sage_const_1  + i] for i in range(_sage_const_2 *m)] + [_sage_const_1 ]
# Let's find roots of Q(y)
